38	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
39	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
40	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
41	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
42	import org.springframework.samples.petclinic.rest.api.OwnersApi;
