46	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
47	import org.springframework.samples.petclinic.rest.dto.VisitDto;
48	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
49	import org.springframework.samples.petclinic.service.ClinicService;
50	import org.springframework.security.access.prepost.PreAuthorize;
51	import org.springframework.web.bind.annotation.CrossOrigin;
52	import org.springframework.web.bind.annotation.RequestMapping;
53	import org.springframework.web.bind.annotation.RestController;
54	import org.springframework.web.util.UriComponentsBuilder;
55	
56	import jakarta.transaction.Transactional;
57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    /**
68	     * A pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
69	     * and a dotted domain. Deliberately conservative so obviously malformed values (e.g. a bare
70	     * word with no {@code @}) are rejected while ordinary addresses are accepted.
71	     */
72	    private static final Pattern EMAIL_PATTERN =
73	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
74	
75	    private final ClinicService clinicService;
76	
77	    private final OwnerMapper ownerMapper;
78	
79	    private final PetMapper petMapper;
80	
81	    private final VisitMapper visitMapper;
82	
83	    public OwnerRestControllerV1(ClinicService clinicService,
84	                                 OwnerMapper ownerMapper,
85	                                 PetMapper petMapper,
86	                                 VisitMapper visitMapper) {
87	        this.clinicService = clinicService;
88	        this.ownerMapper = ownerMapper;
89	        this.petMapper = petMapper;
90	        this.visitMapper = visitMapper;
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
96	        Collection<Owner> owners;
97	        if (lastName != null) {
98	            owners = this.clinicService.findOwnerByLastName(lastName);
99	        } else {
100	            owners = this.clinicService.findAllOwners();
101	        }
102	        if (owners.isEmpty()) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
111	        Owner owner = this.clinicService.findOwnerById(ownerId);
112	        if (owner == null) {
113	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
114	        }
115	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
121	        List<String> missingFields = new ArrayList<>();
122	        if (isBlank(ownerFieldsDto.getFirstName())) {
123	            missingFields.add("firstName");
124	        }
125	        if (isBlank(ownerFieldsDto.getLastName())) {
126	            missingFields.add("lastName");
127	        }
128	        if (isBlank(ownerFieldsDto.getAddress())) {
129	            missingFields.add("address");
130	        }
131	        if (isBlank(ownerFieldsDto.getCity())) {
132	            missingFields.add("city");
133	        }
134	        if (isBlank(ownerFieldsDto.getTelephone())) {
135	            missingFields.add("telephone");
136	        }
137	        if (!missingFields.isEmpty()) {
138	            throw new MissingOwnerFieldsException(missingFields);
139	        }
140	        String lastName = normalizeHousehold(ownerFieldsDto.getLastName());
141	        String address = normalizeHousehold(ownerFieldsDto.getAddress());
142	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
143	            .filter(existing -> lastName.equals(normalizeHousehold(existing.getLastName()))
144	                && address.equals(normalizeHousehold(existing.getAddress())))
145	            .toList();
146	        String householdId = null;
147	        if (!householdMembers.isEmpty()) {
148	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
149	                throw new DuplicateHouseholdException(
150	                    "an owner with the same last name and address already exists");
151	            }
152	            // Joining an existing household: share a stable identifier with every member,
153	            // backfilling any members created before the household was formed.
154	            householdId = householdId(lastName, address);
155	            for (Owner member : householdMembers) {
156	                if (!householdId.equals(member.getHouseholdId())) {
157	                    member.setHouseholdId(householdId);
158	                    this.clinicService.saveOwner(member);
159	                }
160	            }
161	        }
162	        String telephone = toE164(ownerFieldsDto.getTelephone());
163	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
164	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
165	        if (telephoneInUse) {
166	            throw new DuplicateTelephoneException(
167	                "an owner with the same E.164 telephone already exists");
168	        }
169	        ownerFieldsDto.setTelephone(telephone);
170	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
171	        HttpHeaders headers = new HttpHeaders();
172	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
173	        if (owner.getRegistrationDate() == null) {
174	            owner.setRegistrationDate(LocalDate.now());
175	        }
176	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
177	        owner.setHouseholdId(householdId);
178	        this.clinicService.saveOwner(owner);
179	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
180	        headers.setLocation(UriComponentsBuilder.newInstance()
181	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
182	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
183	    }
184	
185	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
186	    @Override
187	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
188	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
189	        if (currentOwner == null) {
190	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
191	        }
192	        currentOwner.setAddress(ownerFieldsDto.getAddress());
193	        currentOwner.setCity(ownerFieldsDto.getCity());
194	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
195	        currentOwner.setLastName(ownerFieldsDto.getLastName());
196	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
197	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
198	        this.clinicService.saveOwner(currentOwner);
199	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
200	    }
201	
202	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
203	    @Transactional
204	    @Override
205	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
206	        Owner owner = this.clinicService.findOwnerById(ownerId);
207	        if (owner == null) {
208	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
209	        }
210	        this.clinicService.deleteOwner(owner);
211	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
212	    }
213	
214	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
215	    @Override
216	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
217	        Owner owner = this.clinicService.findOwnerById(ownerId);
218	        if (owner == null) {
219	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
220	        }
221	        HttpHeaders headers = new HttpHeaders();
222	        Pet pet = petMapper.toPet(petFieldsDto);
223	        owner.setId(ownerId);
224	        pet.setOwner(owner);
225	        pet.getType().setName(null);
226	        this.clinicService.savePet(pet);
227	        PetDto petDto = petMapper.toPetDto(pet);
228	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
229	            .buildAndExpand(pet.getId()).toUri());
230	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
231	    }
232	
233	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
234	    @Override
235	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
236	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
237	        if (currentOwner != null) {
238	            Pet currentPet = this.clinicService.findPetById(petId);
239	            if (currentPet != null) {
240	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
241	                currentPet.setName(petFieldsDto.getName());
242	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
243	                this.clinicService.savePet(currentPet);
244	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
245	            }
246	        }
247	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
248	    }
249	
250	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
251	    @Override
252	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
253	        HttpHeaders headers = new HttpHeaders();
254	        Visit visit = visitMapper.toVisit(visitFieldsDto);
255	        Pet pet = new Pet();
256	        pet.setId(petId);
257	        visit.setPet(pet);
258	        this.clinicService.saveVisit(visit);
259	        VisitDto visitDto = visitMapper.toVisitDto(visit);
260	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
261	            .buildAndExpand(visit.getId()).toUri());
262	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
263	    }
264	
265	
266	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
267	    @Override
268	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
269	        Owner owner = this.clinicService.findOwnerById(ownerId);
270	        if (owner != null) {
271	            Pet pet = owner.getPet(petId);
272	            if (pet != null) {
273	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
274	            }
275	        }
276	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
277	    }
278	
279	    private static boolean isBlank(String value) {
280	        return value == null || value.isBlank();
281	    }
282	
283	    /**
284	     * Normalizes a value for household-duplicate comparison: leading and trailing whitespace is
285	     * trimmed, every internal run of whitespace is collapsed to a single space, and the result is
286	     * lower-cased so that last names and addresses are compared case-insensitively.
287	     */
288	    private static String normalizeHousehold(String value) {
289	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
290	    }
291	
292	    /**
293	     * Derives the stable {@code householdId} shared by all owners in a household. It is a
294	     * deterministic function of the normalized last name and address, so every owner that
295	     * shares those values maps to the same identifier regardless of creation order.
296	     */
297	    private static String householdId(String normalizedLastName, String normalizedAddress) {
298	        String key = normalizedLastName + "\n" + normalizedAddress;
299	        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
300	    }
301	
302	    /**
303	     * Builds the {@code customerCode} assigned to a new owner, formatted
304	     * {@code '<LAST3>-<NNNN>'}: {@code LAST3} is the upper-cased first three letters of the
305	     * owner's last name, and {@code NNNN} is a global 4-digit zero-padded sequence equal to
306	     * one more than the current number of owners (e.g. {@code 'SMI-0007'}).
307	     */
308	    private String nextCustomerCode(String lastName) {
309	        String letters = lastName == null ? "" : lastName.replaceAll("[^\\p{L}]", "");
310	        String last3 = letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
311	        long sequence = this.clinicService.findAllOwners().size() + 1L;
312	        return String.format("%s-%04d", last3, sequence);
313	    }
314	
315	    /**
316	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. A
317	     * leading {@code '+'} and its country code are kept as-is; otherwise the number is treated as a
318	     * national one, a single leading {@code '0'} is dropped, and the default country code
319	     * {@code '+61'} is prepended. The result must have 8 to 15 digits after the {@code '+'},
320	     * otherwise an {@link InvalidTelephoneException} is raised (reported to the client as 400).
321	     */
322	    private static String toE164(String telephone) {
323	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()-]", "");
324	        String digits;
325	        if (cleaned.startsWith("+")) {
326	            digits = cleaned.substring(1);
327	        } else {
328	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
329	            digits = "61" + national;
330	        }
331	        if (!digits.matches("[0-9]{8,15}")) {
332	            throw new InvalidTelephoneException(
333	                "telephone must form a valid E.164 number with 8 to 15 digits");
334	        }
335	        return "+" + digits;
336	    }
337	
338	    /**
339	     * Email is optional: an absent (or blank) value is left as {@code null}. When a value is
340	     * present it must be a syntactically valid address, otherwise an {@link InvalidEmailException}
341	     * is raised (reported to the client as 400). A valid value is returned lower-cased so it is
342	     * stored and returned in canonical form.
343	     */
344	    private static String normalizeEmail(String email) {
345	        if (isBlank(email)) {
346	            return null;
347	        }
348	        String trimmed = email.trim();
349	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
350	            throw new InvalidEmailException("email must be a syntactically valid address");
351	        }
352	        return trimmed.toLowerCase(Locale.ROOT);
353	    }
354	}
